create table if not exists public.pompkin_reviews(id uuid primary key default gen_random_uuid(),product_id text not null references public.pompkin_products(id) on delete cascade,order_id uuid references public.pompkin_orders(id) on delete set null,user_id uuid not null references public.profiles(id),rating integer not null check(rating between 1 and 5),review_text text,status text not null default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz not null default now());
create table if not exists public.pompkin_review_photos(id uuid primary key default gen_random_uuid(),review_id uuid not null references public.pompkin_reviews(id) on delete cascade,user_id uuid not null references public.profiles(id),image_url text not null,created_at timestamptz not null default now());
alter table public.pompkin_reviews enable row level security; alter table public.pompkin_review_photos enable row level security;
create policy reviews_public_read on public.pompkin_reviews for select using(status='approved' or user_id=auth.uid() or public.is_pompkin_admin()); create policy reviews_customer_write on public.pompkin_reviews for insert with check(auth.uid()=user_id); create policy reviews_customer_update on public.pompkin_reviews for update using(auth.uid()=user_id or public.is_pompkin_admin()); create policy review_photos_read on public.pompkin_review_photos for select using(exists(select 1 from public.pompkin_reviews r where r.id=review_id and (r.status='approved' or r.user_id=auth.uid() or public.is_pompkin_admin()))); create policy review_photos_write on public.pompkin_review_photos for all using(user_id=auth.uid() or public.is_pompkin_admin()) with check(user_id=auth.uid() or public.is_pompkin_admin());
